const ctx = reply[kRouteContext]

// `socket._meta` is set by the router when an onTimeout hook is
// registered. On a keep-alive connection the socket outlives the
// response, so leaving it in place keeps the context, the request and
// the reply reachable until the connection is closed. Only clear it if
// this request still owns it: a concurrent request on the same socket
// (HTTP pipelining) may already have replaced it.
const socket = reply.request.raw.socket
if (socket !== null && socket._meta != null && socket._meta.request === reply.request) {
  // Set to `null` rather than deleting it: the router uses `undefined`
  // to mean "no 'timeout' listener attached to this socket yet".
  socket._meta = null
}

